import{i as e,r as t,s as n,t as r}from"./app-FtcyK8lR.js";var i=JSON.parse(`{"path":"/guide/ui-config/environment.html","title":"环境管理","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1772867174000,"contributors":[{"name":"MurphyYi","username":"MurphyYi","email":"zy84338719@hotmail.com","commits":3,"url":"https://github.com/MurphyYi"}],"changelog":[{"hash":"46a94be73dccfa2afd836e97cca5b5781eccb641","time":1772867174000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"fix: 修复文档中所有内部链接使用相对路径"},{"hash":"afed90e9e326cfca3e3e296457c470d99b134c06","time":1772854292000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 为文档添加界面截图"},{"hash":"acf808fd844d46e164aa5b1e98e65abaf9fa76dd","time":1772854092000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 添加完整的 UI配置流程和平台对接文档"}]},"filePathRelative":"guide/ui-config/environment.md"}`),a={name:`environment.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="环境管理" tabindex="-1"><a class="header-anchor" href="#环境管理">#</a> 环境管理</h1><p>环境是虹桥计划中用于隔离不同部署场景的核心概念。本指南将帮助你创建和管理环境。</p><p><img src="/rainbow_bridge/images/environments-page.png" alt="环境管理页面"></p><h2 id="概念说明" tabindex="-1"><a class="header-anchor" href="#概念说明">#</a> 概念说明</h2><h3 id="什么是环境" tabindex="-1"><a class="header-anchor" href="#什么是环境">#</a> 什么是环境？</h3><p>环境（Environment）用于隔离不同的部署场景，例如：</p><table><thead><tr><th>环境标识</th><th>说明</th><th>典型用途</th></tr></thead><tbody><tr><td><code>dev</code></td><td>开发环境</td><td>本地开发调试</td></tr><tr><td><code>test</code></td><td>测试环境</td><td>功能测试、集成测试</td></tr><tr><td><code>staging</code></td><td>预发布环境</td><td>上线前验证</td></tr><tr><td><code>prod</code></td><td>生产环境</td><td>线上服务</td></tr></tbody></table><h3 id="环境与渠道的关系" tabindex="-1"><a class="header-anchor" href="#环境与渠道的关系">#</a> 环境与渠道的关系</h3><ul><li><strong>环境</strong>：粗粒度隔离，如开发/测试/生产</li><li><strong>渠道</strong>：细粒度隔离，如主渠道/热修复渠道/功能渠道</li></ul><p>一个环境可以包含多个渠道，形成层级结构：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">prod (生产环境)</span>
<span class="line">├── main (主渠道)</span>
<span class="line">├── hotfix (热修复渠道)</span>
<span class="line">└── experiment (实验渠道)</span>
<span class="line"></span>
<span class="line">dev (开发环境)</span>
<span class="line">├── main (主渠道)</span>
<span class="line">└── feature-xxx (功能开发渠道)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="创建环境" tabindex="-1"><a class="header-anchor" href="#创建环境">#</a> 创建环境</h2><h3 id="通过-ui-创建" tabindex="-1"><a class="header-anchor" href="#通过-ui-创建">#</a> 通过 UI 创建</h3><ol><li>访问管理界面：<code>http://localhost:8080/rainbow-bridge</code></li><li>点击左侧导航栏的 <strong>环境管理</strong></li><li>点击 <strong>新建环境</strong> 按钮</li><li>填写环境信息： <ul><li><strong>环境标识</strong>：唯一标识符，如 <code>prod</code></li><li><strong>环境名称</strong>：显示名称，如 <code>生产环境</code></li><li><strong>备注</strong>：可选，描述信息</li></ul></li><li>点击 <strong>确定</strong> 保存</li></ol><h3 id="通过-api-创建" tabindex="-1"><a class="header-anchor" href="#通过-api-创建">#</a> 通过 API 创建</h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/environment/create <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{</span>
<span class="line">    &quot;environment_key&quot;: &quot;prod&quot;,</span>
<span class="line">    &quot;environment_name&quot;: &quot;生产环境&quot;,</span>
<span class="line">    &quot;remark&quot;: &quot;线上生产环境&quot;</span>
<span class="line">  }&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="管理环境" tabindex="-1"><a class="header-anchor" href="#管理环境">#</a> 管理环境</h2><h3 id="查看环境列表" tabindex="-1"><a class="header-anchor" href="#查看环境列表">#</a> 查看环境列表</h3><p><strong>通过 UI</strong>：在环境管理页面可以看到所有环境列表</p><p><strong>通过 API</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> http://localhost:8080/rainbow-bridge/api/v1/environment/list</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="编辑环境" tabindex="-1"><a class="header-anchor" href="#编辑环境">#</a> 编辑环境</h3><ol><li>在环境列表中找到目标环境</li><li>点击 <strong>编辑</strong> 按钮</li><li>修改环境名称或备注</li><li>点击 <strong>确定</strong> 保存</li></ol><div class="hint-container warning"><p class="hint-container-title">注意</p><p>环境标识（environment_key）创建后不可修改，只能修改环境名称和备注。</p></div><h3 id="删除环境" tabindex="-1"><a class="header-anchor" href="#删除环境">#</a> 删除环境</h3><ol><li>在环境列表中找到目标环境</li><li>点击 <strong>删除</strong> 按钮</li><li>确认删除操作</li></ol><div class="hint-container caution"><p class="hint-container-title">警告</p><p>删除环境将同时删除该环境下的所有渠道和配置，此操作不可恢复！</p></div><h2 id="最佳实践" tabindex="-1"><a class="header-anchor" href="#最佳实践">#</a> 最佳实践</h2><h3 id="环境命名规范" tabindex="-1"><a class="header-anchor" href="#环境命名规范">#</a> 环境命名规范</h3><p>推荐使用简洁、有意义的标识符：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"># 推荐的命名方式</span>
<span class="line">dev        - 开发环境</span>
<span class="line">test       - 测试环境</span>
<span class="line">staging    - 预发布环境</span>
<span class="line">prod       - 生产环境</span>
<span class="line">prod-us    - 美国生产环境（多地域部署）</span>
<span class="line">prod-eu    - 欧洲生产环境</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="环境隔离策略" tabindex="-1"><a class="header-anchor" href="#环境隔离策略">#</a> 环境隔离策略</h3><p>根据团队规模选择合适的隔离方式：</p><p><strong>小型团队</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">dev → prod</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>中型团队</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">dev → test → staging → prod</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>大型团队/多地域</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">dev → test → staging → prod-us</span>
<span class="line">                      → prod-eu</span>
<span class="line">                      → prod-ap</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="安全建议" tabindex="-1"><a class="header-anchor" href="#安全建议">#</a> 安全建议</h3><ol><li><strong>生产环境保护</strong>：考虑为生产环境设置访问权限控制</li><li><strong>审计日志</strong>：定期检查生产环境的配置变更</li><li><strong>备份策略</strong>：定期导出生产环境配置</li></ol><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题">#</a> 常见问题</h2><h3 id="q-环境标识可以修改吗" tabindex="-1"><a class="header-anchor" href="#q-环境标识可以修改吗">#</a> Q: 环境标识可以修改吗？</h3><p>A: 不可以。环境标识是系统的唯一标识，创建后不可修改。如需更改，需要创建新环境并迁移配置。</p><h3 id="q-删除环境后数据能恢复吗" tabindex="-1"><a class="header-anchor" href="#q-删除环境后数据能恢复吗">#</a> Q: 删除环境后数据能恢复吗？</h3><p>A: 不能。删除环境会级联删除该环境下的所有渠道和配置，建议删除前先导出备份。</p><h3 id="q-环境数量有限制吗" tabindex="-1"><a class="header-anchor" href="#q-环境数量有限制吗">#</a> Q: 环境数量有限制吗？</h3><p>A: 系统本身没有限制，但建议根据实际需要创建，过多的环境会增加管理复杂度。</p><h2 id="下一步" tabindex="-1"><a class="header-anchor" href="#下一步">#</a> 下一步</h2><ul><li><a href="./channel">渠道管理</a> - 学习如何创建和管理渠道</li><li><a href="./config">配置管理</a> - 了解配置的创建和管理</li><li><a href="./migration">配置迁移</a> - 在环境间迁移配置</li></ul>`,50)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};